# Enhanced logging format for debugging redirects and request latency
log_format redirect_log '$remote_addr - $remote_user [$time_local] '
                        '"$request" $status $body_bytes_sent '
                        '"$http_referer" "$http_user_agent" '
                        'redirect_location="$sent_http_location" '
                        'request_time="$request_time" '
                        'upstream_response_time="$upstream_response_time" '
                        'upstream_connect_time="$upstream_connect_time" '
                        'upstream_header_time="$upstream_header_time" '
                        'upstream_status="$upstream_status" '
                        'upstream_addr="$upstream_addr"';

# Increase maximum upload size
client_max_body_size 250M;

# Disable server-wide redirects
server_name_in_redirect off;
port_in_redirect off;

map $http_upgrade $connection_upgrade {
    default upgrade;
    '' close;
}

server {
    listen 80;
    server_name app.clancal.com clancal.com www.clancal.com kinhearthly.com www.kinhearthly.com;

    # Use enhanced logging for debugging
    access_log /var/log/nginx/access.log redirect_log;

    # Nginx status monitoring
    location /nginx_status {
        stub_status on;

        # Allow only internal requests
        allow 127.0.0.1;        # localhost
        allow 172.16.0.0/12;    # Docker internal network
        deny all;               # deny all other requests

        # Optional: Add custom headers
        add_header Content-Type text/plain;
    }

    # Redirect HTTP to HTTPS
    location / {
        return 301 https://$host$request_uri;
    }

    # Let's Encrypt HTTP challenge
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }
}

server {
    listen 443 ssl;
    server_name app.clancal.com clancal.com www.clancal.com kinhearthly.com www.kinhearthly.com;

    # Use enhanced logging for debugging
    access_log /var/log/nginx/access.log redirect_log;

    # SSL certificates
    ssl_certificate /etc/letsencrypt/live/clancal.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/clancal.com/privkey.pem;

    # SSL configuration
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers on;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;
    ssl_session_tickets off;

    # HSTS (optional, but recommended)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # Security headers
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-within-same-origin" always;

    location /metrics {
        # Allow only internal requests
        allow 127.0.0.1;        # localhost
        allow 172.16.0.0/12;    # Docker internal network
        deny all;               # deny all other requests

        # Proxy to your application
        proxy_pass http://web:8000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Request-ID $http_x_request_id;
    }

    # Root location - special handling to prevent redirect loops
    location = / {
        proxy_pass http://web:8000/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;
        proxy_set_header X-Request-ID $http_x_request_id;
        proxy_redirect off;

        # Add debug header
        add_header X-Debug-Info "Root-Path-Handler" always;
    }

    # Static files are collected into a shared Docker volume by the web container.
    location /static/ {
        alias /static/;
    }

    # Fallback media files are served from a shared Docker volume when local
    # file storage is active. Remote object storage URLs bypass nginx entirely.
    location /media/ {
        alias /media/;
    }

    # WebSocket traffic
    location /ws/ {
        proxy_pass http://web:8000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;
        proxy_set_header X-Request-ID $http_x_request_id;
        proxy_buffering off;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
    }

    # All other locations
    location / {
        # Explicitly set scheme to http to prevent redirect loops
        proxy_pass http://web:8000;

        # Pass the original host header
        proxy_set_header Host $host;

        # Pass client's real IP
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # Tell Django the request was HTTPS
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Host $host;
        proxy_set_header X-Forwarded-Port 443;

        # Pass request ID for end-to-end tracing (from mobile clients)
        proxy_set_header X-Request-ID $http_x_request_id;

        # Prevent Nginx from modifying the Location header from upstream
        proxy_redirect off;

        # Prevent redirect loops by setting absolute_redirect to off
        absolute_redirect off;

        # Add debug header to see if request reaches this block
        add_header X-Debug-Info "Nginx-HTTPS-Location" always;

        # Increase timeouts for debugging
        proxy_connect_timeout 300s;
        proxy_send_timeout 300s;
        proxy_read_timeout 300s;
    }

    # Block common scanning patterns
    location ~ ^/wp-(admin|login|content|includes) {
        deny all;
        return 404;
    }

    # Block PHP files (since this is a Django app)
    location ~ \.(php|phar)$ {
        deny all;
        return 404;
    }

    # Block common CMS admin paths
    location ~ ^/(administrator|admin.php|wp-admin|drupal|joomla) {
        deny all;
        return 404;
    }

    # Block common development files/paths
    location ~ \.(env|git|svn|htaccess|htpasswd)$ {
        deny all;
        return 404;
    }

    # Block common vulnerability scan patterns
    location ~ ^/(phpmyadmin|myadmin|pma|sql|mysql|database|install|setup) {
        deny all;
        return 404;
    }

    # Block XML-RPC
    location = /xmlrpc.php {
        deny all;
        return 404;
    }

    # Block common bot patterns
    location ~ ^/(cgi-bin|bin|perl|git|env|vendor) {
        deny all;
        return 404;
    }

    # Block WordPress and common CMS scans - more comprehensive patterns
    location ~ ^/.*(?:wp-|wordpress|blog|web/wp-|cms|news|site|sites) {
        deny all;
        return 404;
    }

    # Block sensitive files and directories with broader patterns
    location ~ /\.(?:git|env|svn|htaccess|htpasswd|user\.ini|php\.ini|config\.php) {
        deny all;
        return 404;
    }

    # Block WordPress specific XML files
    location ~ /(?:xmlrpc\.php|wp-links-opml\.php|wlwmanifest\.xml) {
        deny all;
        return 404;
    }

    # Block common prefixes and suffixes
    location ~ ^/(?:web|blog|wordpress|wp|new|old|test|tmp|temp|bk|bak|backup|admin|administrator|webadmin)/? {
        deny all;
        return 404;
    }

    # Block common file extensions that shouldn't be directly accessible
    # Note: .json is allowed for API responses
    location ~ \.(php|phar|cgi|pl|py|sh|asp|aspx|jsp|sql|ini|log|env|bak|old|save|test)$ {
        deny all;
        return 404;
    }

}

